import{_ as i,C as e,o as d,c as h,j as s,a as l,E as o,a6 as a}from"./chunks/framework.CCKCzdWs.js";const P=JSON.parse(`{"title":"End the test","description":"End a stopped test where it stands, from the editor, the pause bar, Piwi Picker's Runs window, the desktop app or an agent, and Playwright reports it as skipped.","frontmatter":{"title":"End the test","description":"End a stopped test where it stands, from the editor, the pause bar, Piwi Picker's Runs window, the desktop app or an agent, and Playwright reports it as skipped.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/end-the-test.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/end-the-test.html"}],["meta",{"property":"og:title","content":"End the test | Piwi for Playwright"}],["meta",{"property":"og:description","content":"End a stopped test where it stands, from the editor, the pause bar, Piwi Picker's Runs window, the desktop app or an agent, and Playwright reports it as skipped."}]]},"headers":[],"relativePath":"features/end-the-test.md","filePath":"features/end-the-test.md","lastUpdated":1794477236000}`),p={name:"features/end-the-test.md"};function c(u,t,g,w,f,m){const n=e("Needs"),r=e("DemoExamples");return d(),h("div",null,[t[0]||(t[0]=s("h1",{id:"end-the-test",tabindex:"-1"},[l("End the test "),s("a",{class:"header-anchor",href:"#end-the-test","aria-label":'Permalink to "End the test"'},"​")],-1)),o(n,{fixtures:""}),t[1]||(t[1]=a('<p>At a stop, <strong>End the test</strong> ends the test there, as if it had called <code>test.skip()</code> at that line: the locator call it stopped before never runs (Playwright 1.62 or later), nor the rest of the test, and Playwright reports it as skipped, its <code>skip</code> annotation reading <code>Ended from Piwi</code>. Its result reads <strong>Ended at a stop</strong>, never a plain skip, on the run&#39;s page, the test&#39;s pages, Piwi Picker&#39;s Runs window, the desktop app&#39;s Local runs tray and both editors. The run goes on with its next test. Use it once you have seen what you stopped for, or recorded the steps you were missing, and the rest of the test has nothing to show you.</p><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><p>It is offered at any stop but a failure, with a reporter newer than 0.62.0:</p><ul><li><strong>VS Code</strong>: <strong>End test</strong> in the stopped line&#39;s hover, the status bar beside <strong>Finish</strong>, and <strong>Piwi: End the test here, skipping the rest of it</strong> in the palette. It has no key: bind one in <strong>Preferences: Open Keyboard Shortcuts</strong> (search <code>piwi</code>). - <strong>A JetBrains IDE</strong>: <strong>End Test</strong> in the stopped line&#39;s inlay and the arrow&#39;s menu, <strong>Tools → Piwi → End the Test</strong> and the status bar item&#39;s menu. Give it a key in <strong>Settings → Keymap</strong>. - <strong>The <a href="./editor-breakpoints.html#pause-a-run">pause bar</a></strong>: <strong>End the test</strong>. - <strong>Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a></strong> and the desktop app&#39;s <a href="./desktop-runs.html">Local runs tray</a>: <strong>End the test</strong>, beside <strong>Finish</strong>. - <strong>An <a href="./agent-run-control.html">agent</a></strong>: <code>run_control</code> with <code>end</code>, answered as the test ends.</li></ul><h2 id="while-a-pause-waits-for-a-call" tabindex="-1">While a Pause waits for a call <a class="header-anchor" href="#while-a-pause-waits-for-a-call" aria-label="Permalink to &quot;While a Pause waits for a call&quot;">​</a></h2><p><strong>Pause</strong> stops a test before its next call, so a test inside a long one (a click that waits for a button, a <code>waitForTimeout</code>) stops only once it returns. Meanwhile, with a reporter newer than 0.67.0, the Runs window and the desktop app&#39;s tray say the call it waits in and, for a locator call, how long it has run, and offer <strong>End the test</strong> there. In VS Code, the status bar reads <code>Pausing… 12 s</code>, the call in its tooltip, with <strong>End the test</strong> beside it; in a JetBrains IDE, the status bar item reads <code>Piwi: pausing… · waits in</code> and the call, and <strong>Tools → Piwi → End the Test</strong> ends it:</p><ul><li><strong>A locator call or an assertion</strong>, with Playwright 1.62 or later, is given up at once, and the test is skipped.</li><li><strong>Another call</strong> (a <code>waitForTimeout</code>, a navigation) finishes first, and the test is skipped at its next locator call, or as its function ends.</li></ul><h2 id="what-runs-and-what-does-not" tabindex="-1">What runs, and what does not <a class="header-anchor" href="#what-runs-and-what-does-not" aria-label="Permalink to &quot;What runs, and what does not&quot;">​</a></h2><ul><li><strong>At a locator call or an assertion</strong> (<code>click</code>, <code>fill</code>, <code>expect(locator).toBeVisible()</code>), the call is given up before it runs, with Playwright 1.62 or later; an older one runs it first, and the editor says so. At a <code>page.pause()</code>, nothing after it runs.</li><li><strong>At another call</strong> (a navigation, a key press on the page, <code>page.evaluate</code>), the call runs first: Piwi does not hold it. The test is skipped at its next locator call, or as its function ends, and the editor says so.</li><li><strong>At a failure</strong>, it is not offered: <strong>Resume</strong> lets the test end as it failed, and the failure is kept.</li><li><strong>In a <code>beforeEach</code> hook</strong>, it skips the test. <strong>In an <code>afterEach</code> hook or a fixture&#39;s teardown</strong>, the test&#39;s function already ended: it goes on as <strong>Resume</strong> does, keeping the test&#39;s result, and says so. Piwi never stops in a <code>beforeAll</code> or <code>afterAll</code> hook.</li><li><strong>After it</strong>, the test&#39;s <code>afterEach</code> hooks and its fixtures&#39; teardown run as after any skip, so its page closes as usual, with nothing of Piwi left in it.</li><li><strong>A retry</strong> is an attempt of its own. Playwright does not retry a skipped test; a failure you let end runs the next attempt, which stops at your breakpoints as the first did.</li></ul><h2 id="how-the-result-reads" tabindex="-1">How the result reads <a class="header-anchor" href="#how-the-result-reads" aria-label="Permalink to &quot;How the result reads&quot;">​</a></h2><p>The test keeps Playwright&#39;s status, skipped: it counts among the skipped tests, and its run passes or fails on its other tests. What changes is the mark each tool puts on it:</p><ul><li><strong>The dashboard</strong>: the test&#39;s row on the run page, its execution&#39;s status chip and its line in the test&#39;s recent executions read <strong>Ended at a stop</strong> instead of Skipped, and the run page&#39;s header marks the run beside its status (<strong>Ended at a stop</strong>, or <code>3 ended at a stop</code> for more than one). Copy run summary names them among the skipped: <code>4 skipped (1 ended at a stop)</code>.</li><li><strong>Piwi Picker&#39;s Runs window</strong>: the run&#39;s progress line counts them, <code>9 of 9 tests · 1 ended at a stop</code>, in the window&#39;s language; the desktop app&#39;s Local runs tray reads <code>Passed · 1 ended at a stop</code> once the run ended.</li><li><strong>The editors</strong>: the status bar&#39;s run progress counts them (<code>1 ended at a stop</code>), and the notification of a run the editor started names them beside the skipped, <code>3 passed, 0 failed, 1 skipped (1 ended at a stop)</code>.</li></ul><p>The count reaches the editors, Piwi Picker and the desktop app from a reporter newer than 0.68.0; with an older one they count the test as skipped. The dashboard reads the <code>skip</code> annotation, so it marks results already stored too.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Playwright&#39;s calls alone.</strong> The test&#39;s own code between two calls, a loop or a helper, runs until its next call.</li><li><strong>One test.</strong> It ends the stopped worker&#39;s test; the run&#39;s other tests run. To end the run, <strong>Stop</strong> it (one Piwi started, from the editor, the desktop app or the <a href="./runs-window.html">Runs window</a>) or end it in its terminal.</li></ul><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2>',16)),o(r),t[2]||(t[2]=a('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the other controls at a stop.</li><li><a href="./editor-breakpoints.html">Breakpoints in the browser</a>: the pause bar.</li><li><a href="./runs-window.html">Runs window</a>: the same controls from Piwi Picker.</li><li><a href="./agent-run-control.html">Run control for agents</a>: <code>run_control</code> and the other tools.</li></ul>',2))])}const b=i(p,[["render",c]]);export{P as __pageData,b as default};
